WITH target AS (SELECT 'public.player_game_stats'::regclass AS id),
tree AS (SELECT relid FROM target CROSS JOIN LATERAL pg_partition_tree(target.id)),
incoming AS (
  SELECT c.* FROM pg_constraint c,target WHERE c.contype='f' AND c.confrelid=target.id AND c.conparentid=0
),
dependent_views AS (
  SELECT DISTINCT r.ev_class FROM pg_depend d JOIN pg_rewrite r ON r.oid=d.objid,target
  WHERE d.refclassid='pg_class'::regclass AND d.refobjid=target.id AND d.classid='pg_rewrite'::regclass AND r.ev_class<>target.id
)
SELECT jsonb_build_object(
  'relation',(SELECT jsonb_build_object('kind',relkind,'owner',pg_get_userbyid(relowner),'rls',relrowsecurity,'forceRls',relforcerowsecurity,'replicaIdentity',relreplident,'options',reloptions,'comment',obj_description(c.oid,'pg_class'),'partitions',(SELECT GREATEST(count(*)-1,0) FROM tree)) FROM pg_class c,target WHERE c.oid=target.id),
  'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'collation',a.attcollation::regcollation::text,'storage',a.attstorage,'compression',a.attcompression,'comment',col_description(a.attrelid,a.attnum)) ORDER BY a.attnum) FROM pg_attribute a JOIN target ON a.attrelid=target.id LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped),
  'constraints',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid,true),'validated',c.convalidated,'comment',obj_description(c.oid,'pg_constraint')) ORDER BY c.conname),'[]') FROM pg_constraint c,target WHERE c.conrelid=target.id),
  'incomingForeignKeys',(SELECT COALESCE(jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid,true),'validated',c.convalidated,'comment',obj_description(c.oid,'pg_constraint')) ORDER BY c.conrelid::regclass::text,c.conname),'[]') FROM incoming c),
  'indexes',(SELECT jsonb_agg(jsonb_build_object('name',i.indexrelid::regclass::text,'definition',pg_get_indexdef(i.indexrelid),'primary',i.indisprimary,'unique',i.indisunique,'valid',i.indisvalid,'replicaIdentity',i.indisreplident,'clustered',i.indisclustered,'comment',obj_description(i.indexrelid,'pg_class')) ORDER BY i.indexrelid::regclass::text) FROM pg_index i,target WHERE i.indrelid=target.id),
  'triggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled,'oldTable',t.tgoldtable,'newTable',t.tgnewtable,'comment',obj_description(t.oid,'pg_trigger')) ORDER BY t.tgname) FROM pg_trigger t,target WHERE t.tgrelid=target.id AND NOT t.tgisinternal),
  'policies',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(SELECT jsonb_agg(CASE WHEN role=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role) END ORDER BY role) FROM unnest(p.polroles) role),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid),'comment',obj_description(p.oid,'pg_policy')) ORDER BY p.polname),'[]') FROM pg_policy p,target WHERE p.polrelid=target.id),
  'grants',(SELECT jsonb_agg(jsonb_build_object('role',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee,a.privilege_type) FROM pg_class c,target CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid=target.id),
  'views',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',v.ev_class::regclass::text,'definition',pg_get_viewdef(v.ev_class,true),'options',c.reloptions) ORDER BY v.ev_class::regclass::text),'[]') FROM dependent_views v JOIN pg_class c ON c.oid=v.ev_class),
  'rowTypeFunctions',(SELECT COALESCE(jsonb_agg(jsonb_build_object('identity',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid)) ORDER BY p.oid::regprocedure::text),'[]') FROM pg_proc p,target JOIN pg_class c ON c.oid=target.id WHERE p.prorettype=c.reltype OR c.reltype=ANY(p.proargtypes::oid[]) OR c.reltype=ANY(p.proallargtypes)),
  'publications',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',p.pubname,'columns',r.prattrs::text,'filter',pg_get_expr(r.prqual,r.prrelid)) ORDER BY p.pubname),'[]') FROM pg_publication_rel r JOIN pg_publication p ON p.oid=r.prpubid,target WHERE r.prrelid=target.id),
  'retention',(SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.relation_name),'[]') FROM private.retention_rules r WHERE r.relation_name='public.player_game_stats' OR r.relation_name LIKE 'public.player_game_stats_%' OR r.relation_name='private.player_stats_partitions'),
  'dependencies',(SELECT jsonb_agg(jsonb_build_object('class',d.classid::regclass::text,'object',pg_describe_object(d.classid,d.objid,d.objsubid),'type',d.deptype)) FROM pg_depend d,target WHERE d.refobjid=target.id AND d.refclassid='pg_class'::regclass)
);
